      "name": "Closed-loop control",
      "definition": "A control strategy where a sensor (e.g., wheel encoder) measures the actual output, compares it to a setpoint to calculate an error, and uses that error to correct the input command in real-time, unlike open-loop control which relies on fixed inputs without feedback.",
      "prerequisite_names": ["Open-loop control"]
    },
    {
      "citations": [1, 2, 3],
      "name": "Error signal",
      "definition": "The difference between the desired setpoint and the measured value, denoted as e(t), which drives the controller's corrective action.",
      "prerequisite_names": ["Closed-loop control"]
    },
    {
      "citations": [2, 3],
      "name": "Steady-state error",
      "definition": "The remaining difference between the setpoint and the actual value after the system has settled, often caused by insufficient control authority near the target to overcome static friction when using proportional control alone.",
      "prerequisite_names": ["Proportional control", "Closed-loop control"]
    },
    {
      "citations": [2, 3],
      "name": "Integral windup",
      "definition": "A phenomenon in PID control where the integral term accumulates a large error while the actuator is saturated (e.g., at full power), leading to excessive overshoot and oscillation once the actuator is no longer saturated.",
      "prerequisite_names": ["Integral control", "Closed-loop control"]
    },
    {
      "citations": [3, 4],
      "name": "PID controller tuning",
      "definition": "The process of adjusting the proportional (Kp), integral (Ki), and derivative (Kd) gains to achieve desired system performance, typically involving increasing Kp until oscillation occurs, adding Ki to eliminate steady-state error, and adding Kd to reduce overshoot and damp motion.",
      "prerequisite_names": ["Proportional control", "Integral control", "Derivative control", "Closed-loop control"]
    }
  ]
}

